#!/usr/bin/env python3
"""Author-selected Western history expansion; regenerate from unchanged source notes.

The seeds select separate retrieval, comparison, causal and source-reading targets.
Imported transcriptions are evidence, not a claim of official KICE answer verification.
Known source errors (including FDR election date and mixed German constitutions) are
excluded. No source text is paraphrased and then represented as an exact quotation.
"""
from pathlib import Path
import json, re, collections
ROOT=Path(__file__).resolve().parents[2]
NOTES={n['id']:n for n in json.loads((ROOT/'public/data/subjects/seoyangsa/notes.json').read_text())}
Q=[]
def ev(spec):
    out=[]
    for item in spec.split(';'):
        ref,anchor=item.split(':',1)
        page='seoyangsa-'+('gichul' if ref.startswith('g') else 'textbook')+'-page-'+ref.lstrip('tg')
        width=3
        if '@' in anchor:
            anchor,raw_width=anchor.rsplit('@',1);width=int(raw_width)
        text=NOTES[page]['text']; lines=text.splitlines(keepends=True)
        matches=[i for i,line in enumerate(lines) if anchor in line]
        if not matches: raise ValueError(f'Missing anchor {page}: {anchor}')
        i=matches[0]
        # A short contiguous source window retains exact whitespace and punctuation.
        quote=''.join(lines[i:min(i+width,len(lines))]).strip()
        out.append({'page':page,'quote':quote})
    return list({(x["page"],x["quote"]):x for x in out}.values())

def add(kind,unit,prompt,answer,explain,spec,skill='fact',**extra):
    q={'id':f'seoyangsa-ext-{unit}-{len(Q)+1:03d}','type':kind,'skill':skill,'prompt':prompt,'answer':answer,'explain':explain,'evidence':ev(spec),**extra}
    Q.append(q);return q

def mc(unit,rows):
    for row in rows.strip().splitlines():
        p,a,w1,w2,w3,spec,why,skill=row.split('|')
        wrong=[w.split('~',1) for w in (w1,w2,w3)]
        choices=[a]+[w[0] for w in wrong]; explanations=[why]+[w[1] for w in wrong]
        shift=len(Q)%4
        choices=choices[-shift:]+choices[:-shift] if shift else choices
        explanations=explanations[-shift:]+explanations[:-shift] if shift else explanations
        add('mc',unit,p,shift,why,spec,skill,choices=choices,choiceExplanations=explanations)

