def blank(unit,rows):
    for row in rows.strip().splitlines():
        ref,answer,anchor,why=row.split('|')
        page='seoyangsa-'+('gichul' if ref.startswith('g') else 'textbook')+'-page-'+ref.lstrip('tg')
        lines=NOTES[page]['text'].splitlines(keepends=True)
        min_lines=1
        if '@' in anchor:
            anchor,raw_min=anchor.rsplit('@',1);min_lines=int(raw_min)
        candidates=[]
        for i,line in enumerate(lines):
            if anchor not in line:continue
            for before,after in [(0,n) for n in range(min_lines,max(min_lines+1,5))]+[(1,n) for n in range(max(2,min_lines),5)]:
                passage=''.join(lines[max(0,i-before):i+after]).strip()
                if passage.count(answer)==1 and '**' not in passage and len(passage)>=32:
                    candidates.append(passage);break
        if not candidates:raise ValueError(f'No blank passage {ref}: {answer} / {anchor}')
        passage=candidates[0]
        if answer=='솔리두스':
            passage=passage[:passage.index('시도.')+3]
        q=add('blank',unit,passage.replace(answer,'_____'),answer,why,ref+':'+anchor,'source-analysis',passage=passage)
        q['evidence']=[{'page':page,'quote':passage}]

