def essay(unit,title,prompt,parts,skill='comparison'):
    rubric=[];evidence=[]
    for i,(label,answer,spec,checks) in enumerate(parts):
        points=[3,3,4][i];support=ev(spec);evidence.extend(support)
        rubric.append({'id':f'r{i+1}','label':label,'max':points,'ok':answer,'evidence':support,
          'checkpoints':checks.split(' / '),'allowedScores':list(range(points+1)),
          'rejectConditions':['이 기준의 핵심 관계를 반대로 서술하거나 다른 시대·제도의 설명으로 대체한 경우 해당 요소를 인정하지 않는다.']})
    q=add('essay',unit,prompt,' '.join(p[1] for p in parts),'세 요구조건을 구분해 채점한다. 같은 의미의 표현은 인정하되 이름의 단순 나열만으로 비교·인과 관계를 충족했다고 보지 않는다.',parts[0][2],skill,title=title,rubric=rubric)
    q['evidence']=list({(x['page'],x['quote']):(x) for x in evidence}.values())

