essay('postwar-change','소련 개혁과 유럽 질서의 전환','1980년대 말~1991년의 변화를 ① 글라스노스트와 페레스트로이카의 구별 ② 동유럽 개혁과 독일 통일 ③ 소련 해체까지의 시간 순서로 설명하시오.',[
('개혁 용어','글라스노스트는 공개·개방을, 페레스트로이카는 체제의 개혁·재건을 강조했다. 정치적 공개와 경제·사회 개편은 관련되지만 같은 단어는 아니다.','263:글라스노스트(개방)@1;263:페레스트로이카(재편)@1','공개·개방 / 개혁·재건의 구별'),
('유럽의 변화','동유럽의 공산당 지배가 흔들리고 1989년 베를린 장벽이 붕괴한 뒤 1990년 독일 통일이 이루어졌다.','264:베를린 장벽 개방@2;264:1990. 3. 총선@1','동유럽 체제 변화 / 장벽 붕괴와 통일의 순서'),
('소련의 해체','소련은 1991년에 해체되었다. 장벽 붕괴·독일 통일·소련 해체는 관련된 과정이지만 연도와 국가적 사건을 동일하게 처리해서는 안 된다.','264:1991 연방 해체@1','1991년 소련 해체 / 세 사건의 구별과 정확한 선후')])

def main():
    assert len(Q)==300, len(Q)
    assert collections.Counter(q['type'] for q in Q)=={'mc':100,'short':100,'blank':70,'essay':30}
    for q in Q:
        for x in q['evidence']:
            assert x['quote'] in NOTES[x['page']]['text'], q['id']
            assert '루스벨트 당선(1933)' not in x['quote'], q['id']
    target=ROOT/'tools/history-questions/extended-inputs/seoyangsa.json'
    target.write_text(json.dumps({'schemaVersion':1,'subject':'seoyangsa','questions':Q},ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'questions':len(Q),'types':dict(collections.Counter(q['type'] for q in Q)),'skills':dict(collections.Counter(q['skill'] for q in Q)),'sourcePages':len({e['page'] for q in Q for e in q['evidence']})},ensure_ascii=False))
if __name__=='__main__':main()
